// ================= SETTINGS (fill these in) =================
const STEAM_API_KEY = '***REDACTED***';
const STEAM_ID = '76561198347493742';
// =============================================================

const api = 'https://api.steampowered.com';
const get = (path, qs) =>
  this.helpers.httpRequest({ method: 'GET', url: api + path, qs: { key: STEAM_API_KEY, ...qs }, json: true });

const input = $input.first().json;
const wanted = String(input.game ?? input.query ?? '').trim();
const norm = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, '');

async function progressFor(appid) {
  const res = await get('/ISteamUserStats/GetPlayerAchievements/v1/', { steamid: STEAM_ID, appid, l: 'english' });
  const list = res?.playerstats?.achievements ?? [];
  const total = list.length;
  const done = list.filter(a => a.achieved === 1);
  return { list, total, unlocked: done.length, percent: total ? Math.round(done.length / total * 100) : 0 };
}

// ---------- No game named: overview of recently played games ----------
if (!wanted) {
  const recent = await get('/IPlayerService/GetRecentlyPlayedGames/v1/', { steamid: STEAM_ID, count: 5 });
  const games = recent?.response?.games ?? [];
  if (!games.length) return [{ json: { result: 'No games played on Steam in the last 2 weeks.' } }];
  const lines = [];
  for (const g of games) {
    try {
      const p = await progressFor(g.appid);
      lines.push(p.total
        ? `${g.name}: ${p.unlocked}/${p.total} achievements (${p.percent}%), ${(g.playtime_forever / 60).toFixed(1)} h total`
        : `${g.name}: no achievements`);
    } catch (e) {
      lines.push(`${g.name}: achievements unavailable`);
    }
  }
  return [{ json: { result: 'Recently played games:\n' + lines.join('\n') } }];
}

// ---------- Find the game in the user's library ----------
const owned = await get('/IPlayerService/GetOwnedGames/v1/', {
  steamid: STEAM_ID, include_appinfo: 1, include_played_free_games: 1,
});
const library = owned?.response?.games ?? [];
if (!library.length) {
  return [{ json: { result: 'Could not read the Steam library. The profile\'s "Game details" may be private.' } }];
}

const w = norm(wanted);
let game = library.find(g => norm(g.name) === w)
  ?? library.filter(g => norm(g.name).includes(w)).sort((a, b) => b.playtime_forever - a.playtime_forever)[0]
  ?? library.filter(g => w.includes(norm(g.name)) && norm(g.name).length > 3)[0];

if (!game) {
  const words = wanted.toLowerCase().split(/\s+/).filter(x => x.length > 2);
  const similar = library
    .map(g => ({ g, score: words.filter(x => g.name.toLowerCase().includes(x)).length }))
    .filter(x => x.score > 0).sort((a, b) => b.score - a.score).slice(0, 5).map(x => x.g.name);
  return [{ json: { result: `No game called "${wanted}" in the Steam library.` + (similar.length ? ` Similar: ${similar.join(', ')}` : '') } }];
}

// ---------- Achievement progress for that game ----------
let p;
try {
  p = await progressFor(game.appid);
} catch (e) {
  return [{ json: { result: `${game.name} has no achievements, or its achievement data is private.` } }];
}
if (!p.total) return [{ json: { result: `${game.name} has no achievements.` } }];

// How rare each achievement is among all players (to suggest the easiest next ones)
const rarity = {};
try {
  const g = await get('/ISteamUserStats/GetGlobalAchievementPercentagesForApp/v2/', { gameid: game.appid });
  for (const a of g?.achievementpercentages?.achievements ?? []) rarity[a.name] = parseFloat(a.percent);
} catch (e) { /* optional */ }

const locked = p.list.filter(a => a.achieved !== 1)
  .sort((a, b) => (rarity[b.apiname] ?? 0) - (rarity[a.apiname] ?? 0));
const recent = p.list.filter(a => a.achieved === 1)
  .sort((a, b) => b.unlocktime - a.unlocktime).slice(0, 5);

const fmt = (a) => {
  const r = rarity[a.apiname];
  return `- ${a.name || a.apiname}: ${a.description || '(hidden achievement)'}` + (r !== undefined ? ` [${r.toFixed(1)}% of players have it]` : '');
};

let result = `${game.name}\n`
  + `Progress: ${p.unlocked}/${p.total} achievements (${p.percent}%)` + (p.unlocked === p.total ? ' - PLATINUM (100%) done!' : '') + '\n'
  + `Remaining: ${p.total - p.unlocked}\n`
  + `Playtime: ${(game.playtime_forever / 60).toFixed(1)} hours\n`;
if (recent.length) {
  result += `\nMost recent unlocks:\n` + recent.map(a =>
    `- ${a.name || a.apiname} (${new Date(a.unlocktime * 1000).toLocaleDateString('en-GB', { timeZone: 'Asia/Amman' })})`).join('\n') + '\n';
}
if (locked.length) {
  result += `\nStill locked (easiest first, ${Math.min(locked.length, 20)} of ${locked.length} shown):\n`
    + locked.slice(0, 20).map(fmt).join('\n');
}

return [{ json: { result } }];
